using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckSkeeBall {
public sealed class SkeeMatch:SportsEventSession {
 public SkeeRunner[] courses;public Transform[] arenas;public SkeeRules rules=new SkeeRules();public float Clock{get;private set;}public int ActiveCourses{get;private set;}public int Launches{get;private set;}public int GenuineEntries{get;private set;}public bool HotSeat=>option==1;public readonly bool[] cab={true,true,true,true,true,true,true,true};readonly Vector3[] targets=new Vector3[8];readonly float[] speed=new float[8],think=new float[8];readonly Vector2[] ai=new Vector2[8];readonly StringBuilder text=new StringBuilder(700);int mouseOwner=-1;
 public override string Title=>"TRUCK SKEE-BALL";public override int MinimumPlayers=>1;public override int MaximumPlayers=>8;public override int SetupMaximumPlayers=>HotSeat?8:4;public override int OptionCount=>2;public override int WeatherCount=>1;public override bool MultiViewHUD=>Running&&!Finished;public override string OptionLabel=>HotSeat?"HOT SEAT · UP TO EIGHT":"SIMULTANEOUS · FOUR EQUIVALENT LANES";
 public override void NormalizeSetup(){base.NormalizeSetup();setup.count=Mathf.Min(setup.count,SetupMaximumPlayers);setup.mode=HotSeat?BowlingMode.HotSeat:BowlingMode.Simultaneous;setup.sharedHotSeat=HotSeat;}
 public override string Help=>"YOUR TRUCK IS THE SKEE-BALL\nNine launches each. Drive down the approach and up the actual curved EasyRoads ramp. Entry speed, angle and alignment create the flight; there is no launch button or automatic scoring trajectory. REVERSE brakes before reversing. Limited aftertouch nudges lateral/range flight; release forward/back after launch to arm range correction. It cannot hover or change vertical flight. The first target-board contact disables all aftertouch and propulsion.\n\nEnter the real open rings:10,20,30,40,50 or the two100-point corners. Your entire authoritative truck must pass through the same opening. A rim/outside hit, miss, approach fall or genuine bounded simulation failure is zero. Swept whole-body crossing prevents fast rear-chassis skips. One award per numbered delivery.\n\nUp to four simultaneous separate lanes, each progressing independently. Hot seat supports up to eight and rotates participants after each delivery. Tied leaders get one equal-opportunity extra launch each until resolved; everyone completes their nine before extras begin. Solo retains a personal best. Same NWH wheels, ramp, gravity, control limits and scoring apply to AI.\n\nCab view defaults for humans. Fresh ACTION during approach/flight switches your cab/chase view without affecting the truck. Whole-pad right stick or the explicitly owned mouse looks in the cab; shared sticks retain fixed cameras. Recorded landing replays: LEFT/RIGHT changes angle, FORWARD/BACK chooses fast/slow, ACTION skips after a neutral release. AI replays are brief. Your replay never pauses another lane. Shared settings, pause/reconnect and rematches preserve normal ownership. Offline only.";
 public override string Header=>Title+" · NINE LAUNCHES";public override string Status=>rules.ExtraRound>0?"EQUAL-OPPORTUNITY EXTRA LAUNCH "+rules.ExtraRound:"ACTUAL CURVED RAMP · OPEN HOLES · NO AUTO AIM";
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  ").Append(rules.totals[i]).Append(" PTS · ").Append(rules.attempts[i]).Append(" / ").Append(rules.required[i]).Append(" LAUNCHES\n");return text.ToString();}}
 public int ResultPlace(int slot)=>LWS.TruckSports.SportsResultPlacings.FromFinalTotals(slot,setup.count,rules.totals,rules.Winner);
 public int ResultPersonalBest=>SportsPrefs.GetInt("TruckSkeeBall.Best",0);
 public override string Results=>(setup.count==1?"SOLO TOTAL "+rules.totals[0]+" · BEST "+SportsPrefs.GetInt("TruckSkeeBall.Best",0):rules.Winner>=0?setup.players[rules.Winner].name+" WINS THE LANES":"COMPLETE")+"\n\n"+Standings;
 readonly int[] cameraCourses=new int[4];
 public override string ViewText(int view){var r=courses[cameraCourses[view]];int owner=r.owner;string phase=r.Phase==SkeePhase.Approach?"DRIVE / ALIGN · ACTION CAB / CHASE":r.Phase==SkeePhase.Flight?"AFTERTOUCH "+Mathf.RoundToInt(Mathf.Max(0,1-r.touch.Spent/1.25f)*100)+"%":r.Phase==SkeePhase.Replay?"REPLAY · LEFT/RIGHT ANGLE · UP/DOWN SPEED · ACTION SKIP":r.Phase==SkeePhase.Result?(r.Award>0?"IN THE RING · +"+r.Award:"MISS · ZERO"):r.Phase==SkeePhase.Waiting?"COMPLETE · WAITING FOR OTHER LANES":r.Phase==SkeePhase.Landing?"PHYSICAL LANDING · NO CONTROL":"PREPARE TO LAUNCH";return "<color=#"+ColorUtility.ToHtmlStringRGB(setup.players[owner].color)+">"+setup.players[owner].name+"</color> · "+rules.totals[owner]+" PTS · "+Mathf.Min(r.Delivery,rules.required[owner])+" / "+rules.required[owner]+"\n"+phase+"\n"+(r.truck.body.linearVelocity.magnitude*2.236936f).ToString("F0")+" MPH · "+Controls(owner)+"\nRINGS 10 / 20 / 30 / 40 / 50 / 100";}
 public override bool TryReadViewportCard(int view,out int participant,out string score,out string detail){participant=-1;score=detail=null;if(cameras==null||view<0||view>=cameras.Length||cameras[view]==null||!cameras[view].enabled)return false;participant=courses[cameraCourses[view]].owner;if(participant<0||participant>=setup.count)return false;score=rules.totals[participant].ToString();detail=rules.attempts[participant]+" / "+rules.required[participant]+" LAUNCHES";return true;}
 protected override void Awake(){base.Awake();SportsLookOptions.Load();}
 public bool IsAI(int owner)=>setup.players[owner].source==BowlingSource.AI;
 protected override void BeginGame(){rules.Reset(setup.count);Clock=0;Launches=GenuineEntries=0;mouseOwner=-1;for(int i=0;i<setup.count;i++){cab[i]=!IsAI(i);if(mouseOwner<0&&setup.players[i].source==BowlingSource.Keyboard)mouseOwner=i;}ActiveCourses=HotSeat?1:setup.count;for(int i=0;i<4;i++){bool active=i<ActiveCourses;arenas[i].gameObject.SetActive(active);courses[i].truck.gameObject.SetActive(active);courses[i].viewCamera.view.enabled=active;if(!active){courses[i].Freeze();continue;}courses[i].viewCamera.view.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(ActiveCourses,i);courses[i].ResetCourse(i);}int count=HotSeat?1:SportsCameraOptions.SelectOrSpectate(setup,cameraCourses);if(HotSeat)cameraCourses[0]=0;foreach(var course in courses)course.viewCamera.view.enabled=false;cameras=new Camera[count];for(int view=0;view<count;view++){var camera=courses[cameraCourses[view]].viewCamera.view;camera.enabled=true;camera.rect=LWS.TruckCornhole.CornholeMatch.ViewRect(count,view);cameras[view]=camera;}}
 // Measured from nine injected ordinary-control approaches on this exact physical ramp.
 // This estimates a control setting only; no trajectory, impulse or score is supplied to a truck.
 static readonly float[] measuredHeight={3.477f,8.376f,15.957f,20.388f,23.737f,27.128f,33.859f,35.127f,42.967f};
 static float ApproachForHeight(float height){for(int i=1;i<measuredHeight.Length;i++)if(height<=measuredHeight[i])return Mathf.Lerp(18+(i-1)*2,18+i*2,Mathf.InverseLerp(measuredHeight[i-1],measuredHeight[i],height));return 34;}
 public void Plan(SkeeRunner r){int owner=r.owner;int skill=(int)setup.players[owner].difficulty;var random=new System.Random(19377+owner*101+rules.attempts[owner]*7919);int[] choices=skill==0?new[]{0,0,1,1,2}:skill==1?new[]{0,1,1,2,2,3,5}:new[]{1,2,3,5,5,4,6};var ring=r.rings[choices[random.Next(choices.Length)]];float spread=skill==0?1.8f:skill==1?.75f:.2f;var local=new Vector3(ring.center.x+(float)(random.NextDouble()*2-1)*spread,ring.center.y+(float)(random.NextDouble()*2-1)*spread,0);targets[owner]=r.target.TransformPoint(local);float execution=skill==0?.75f:skill==1?.4f:.12f;speed[owner]=Mathf.Clamp(ApproachForHeight(local.y)+(float)(random.NextDouble()*2-1)*execution+Mathf.Abs(local.x)*.015f,17.5f,34);think[owner]=0;ai[owner]=Vector2.zero;}
 Vector2 Bot(SkeeRunner r,float dt){int owner=r.owner;think[owner]-=dt;if(think[owner]>0)return ai[owner];float skill=(int)setup.players[owner].difficulty;think[owner]=Mathf.Lerp(.2f,.07f,skill*.5f);var p=r.truck.body.position;if(r.Phase==SkeePhase.Approach){float exitX=Mathf.Clamp(targets[owner].x-r.Center,-2.5f,2.5f);float yaw=Mathf.Atan2(targets[owner].x-r.Center-exitX,Mathf.Max(10,targets[owner].z-44));float z=p.z+6;float line=exitX+Mathf.Tan(yaw)*(z-44);line=Mathf.Lerp(0,line,Mathf.InverseLerp(14,32,p.z));var intended=new Vector3(r.Center+line,p.y,z);var forward=Vector3.ProjectOnPlane(r.truck.body.rotation*Vector3.forward,Vector3.up);float steering=Vector3.SignedAngle(forward,intended-p,Vector3.up)/27;float velocity=Vector3.Dot(r.truck.body.linearVelocity,r.truck.body.rotation*Vector3.forward);float desired=speed[owner];ai[owner]=new Vector2(Mathf.Clamp(steering,-1,1),velocity<desired-.25f?1:velocity>desired+.6f?-1:0);}
 else if(r.Phase==SkeePhase.Flight){var v=r.truck.body.linearVelocity;var normal=r.target.forward;float distance=Vector3.Dot(p-r.target.position,normal),normalSpeed=Vector3.Dot(v,normal),normalGravity=Vector3.Dot(Physics.gravity,normal);float discriminant=normalSpeed*normalSpeed-2*normalGravity*distance;float time=Mathf.Clamp(Mathf.Abs(normalGravity)>.01f&&discriminant>=0?(-normalSpeed+Mathf.Sqrt(discriminant))/normalGravity:(targets[owner].z-p.z)/Mathf.Max(3,v.z),0,5);var predicted=p+v*time+Physics.gravity*(.5f*time*time);ai[owner]=new Vector2(Mathf.Clamp((targets[owner].x-predicted.x)*.3f,-1,1),r.FlightAge<.35f?0:Mathf.Clamp((targets[owner].y-predicted.y)*.15f,-1,1));}else ai[owner]=Vector2.zero;return ai[owner];}
 protected override void Simulate(float dt){Clock+=dt;for(int i=0;i<ActiveCourses;i++)courses[i].Observe();for(int i=0;i<ActiveCourses;i++){var r=courses[i];if(r.Done){if(!HotSeat&&rules.CanLaunch(r.owner))r.StartAttempt();continue;}var input=IsAI(r.owner)?Bot(r,dt):commands[r.owner];bool action=!IsAI(r.owner)&&actions[r.owner];if(action&&(r.Phase==SkeePhase.Approach||r.Phase==SkeePhase.Flight)){cab[r.owner]=!cab[r.owner];r.look.ResetLook();}r.Tick(input,action,dt);}if(rules.Complete){bool done=true;for(int i=0;i<ActiveCourses;i++)done&=courses[i].Done;if(done){if(setup.count==1){SportsPrefs.SetInt("TruckSkeeBall.Best",Mathf.Max(rules.totals[0],SportsPrefs.GetInt("TruckSkeeBall.Best",0)));SportsPrefs.Save();}EndMatch();}}}
 public void AttemptViewed(SkeeRunner r){if(rules.Complete)return;if(!HotSeat){if(rules.CanLaunch(r.owner))r.StartAttempt();return;}for(int n=1;n<=setup.count;n++){int next=(r.owner+n)%setup.count;if(rules.CanLaunch(next)){r.ResetCourse(next);Gate();return;}}}
 public void Launched(SkeeRunner r){Launches++;feedback.Play(0,0,true);Pulse(r.owner,.2f,.1f);}public void Resolved(SkeeRunner r,string reason){if(r.Award>0){GenuineEntries++;ConfirmScore("ring:"+r.owner+":"+r.Delivery,r.owner,r.Award,rules.totals[r.owner],"RING CLEARED",r.Award>=50?SportsScoreTier.Major:SportsScoreTier.Small);}feedback.Play(r.Award>=50?5:r.Award>0?2:3,0,true);Pulse(r.owner,r.Award>0?.3f:.1f,.12f);Debug.Log("SKEE_RESULT owner="+r.owner+" delivery="+r.Delivery+" points="+r.Award+" reason="+reason+" position="+r.truck.body.position+" launch="+r.LaunchVelocity+" aftertouch="+r.touch.Spent);}
 protected override void Present(float dt){for(int i=0;i<ActiveCourses;i++){var r=courses[i];var camera=r.viewCamera;bool replaying=r.ReplayLive;var p=replaying?r.replay.Position(0):r.truck.body.position;var rotation=replaying?r.replay.ghosts[0].rotation:r.truck.body.rotation;bool useCab=!IsAI(r.owner)&&(replaying?r.replay.Angle==0:cab[r.owner]);int mask=(~(15<<25));if(useCab)mask&=~(1<<(10+i));camera.view.cullingMask=mask;r.cabAnchor.gameObject.SetActive(useCab);if(useCab){float yaw=rotation.eulerAngles.y;float pitch=r.Phase==SkeePhase.Approach?Mathf.Clamp(Mathf.DeltaAngle(0,rotation.eulerAngles.x),-60,15):Mathf.Clamp(-Mathf.Atan2(r.target.position.y+12-p.y,Mathf.Max(8,r.target.position.z-p.z))*Mathf.Rad2Deg,-30,35);var basis=Quaternion.Euler(pitch,yaw,0);var position=p+Vector3.up*.78f+Quaternion.Euler(0,yaw,0)*Vector3.forward*.18f;r.cabAnchor.SetPositionAndRotation(position,basis);var look=r.look.Apply(basis,setup.players[r.owner],r.owner,HotSeat||r.owner==mouseOwner,Live&&!replaying,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);camera.view.cullingMask|=1<<(25+i);camera.view.transform.SetPositionAndRotation(position,look);}else{var offset=replaying&&r.replay.Angle==2?new Vector3(-11,8,7):new Vector3(7,7,-12);if(!replaying&&r.Phase==SkeePhase.Flight){var destination=r.target.TransformPoint(new Vector3(0,17.5f,0));float gap=Mathf.Abs(destination.z-p.z);camera.Pose(Vector3.Lerp(p+Vector3.up,destination,.35f),new Vector3(7,9,-12-gap*.4f),66);}else camera.Pose(p+Vector3.up,offset,66);}}}
 protected override void SetPaused(bool pause){if(pause&&courses!=null)foreach(var r in courses)if(r.look!=null)r.look.ReleaseCursor();}protected override void StopGame(){if(courses!=null)foreach(var r in courses)if(r!=null)r.Freeze();}protected override void StopSounds(){if(courses!=null)foreach(var r in courses)if(r!=null)r.truck.StopSound();}
}
}
